head.script:
scwin.fn_GetPar, scwin.fn_SetPar, scwin.fr_SecuGrpId;
scwin.gIsurCd, scwin.gIsurNm, scwin.gInputRnd, scwin.gGubnStat, scwin.gAcptNo;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        let vCurDate = $c.ut.cGetToday("yyyymmdd");
        edt_SDate.setValue(vCurDate);
        $c.cm.PanelToGroupBox(panel_Top);
        btn_Input.hide();
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05960.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name MaxTab_01_OnSelChanged
 * @description Max Tab 01 On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.MaxTab_01_OnSelChanged = async function(nIndex) {
    try {
        let vCurDate = $c.ut.cGetToday("yyyymmdd");
        edt_SDate.setValue(vCurDate);
        if (MaxTab_01.getSelectedTabIndex() === 3) {
            btn_Input.show("");
        } else {
            btn_Input.hide();
        }
        if (MaxTab_01.getSelectedTabIndex() === 2) {
            btn_New.hide();
        } else {
            btn_New.show("");
        }
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05960.MaxTab_01_OnSelChanged" });
    }
};

/**
 * @method
 * @name img_COM_NM_onclick
 * @description img_COM_NM 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_COM_NM_onclick = function() {
    try {
        scwin.fn_GetPar = scwin.getParIsur;
        scwin.fn_SetPar = scwin.setParIsur;
        $c.lc.fn_PopFindCorpChrg(scwin.fr_SecuGrpId);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05960.img_COM_NM_onclick" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onblur
 * @description txb_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            txb_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05960.txb_ISUR_CD_onblur" });
    }
};

/**
 * @method
 * @name btn_SDate_onclick
 * @description btn_SDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDate_onclick = function() {
    try {
        popUpCalendar2(edt_SDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05960.btn_SDate_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05960.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_New_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_New_onclick = async function() {
    try {
        scwin.gGubnStat = "I"; // 입력팝업
        await scwin.openDetail();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05960.btn_New_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05960.btn_Close_onclick" });
    }
};

