/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF05960.xml", SCREN_PROCS_TP_CD_07);
        if (MaxTab_01.getSelectedTabIndex() === 1) {
            $c.data.downloadGridViewExcel(grd_List_1, {fileName: "소속부 인증및 자격", type: "8"});
        } else if (MaxTab_01.getSelectedTabIndex() === 2) {
            $c.data.downloadGridViewExcel(grd_List_2, {fileName: "기술성장기업", type: "8"});
        } else if (MaxTab_01.getSelectedTabIndex() === 3) {
            $c.data.downloadGridViewExcel(grd_List_3, {fileName: "스타라이징", type: "8"});
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05960.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name grd_List_1_OnDblClick
 * @description grd_List_1 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_1_OnDblClick = async function(row, colid) {
    try {
        if (colid === "ISUR_NM") {
            scwin.setContnId(row);
            await scwin.openDetail();
        } else if (colid === "SAVE_FILE_NM") {
            scwin.filedown(dts_List_1);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05960.grd_List_1_OnDblClick" });
    }
};

/**
 * @method
 * @name grd_List_3_OnDblClick
 * @description grd_List_3 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_3_OnDblClick = async function(row, colid) {
    try {
        if (row === 0) return;
        scwin.gIsurCd = dts_List_3.getCellData(row, "ISUR_CD");
        scwin.gIsurNm = dts_List_3.getCellData(row, "ISUR_NM");
        scwin.gInputRnd = dts_List_3.getCellData(row, "INPUT_RND");
        scwin.gGubnStat = "U";
        await scwin.openDetail();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05960.grd_List_3_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_Input_onclick
 * @description 「입력」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Input_onclick = async function() {
    try {
        await scwin.input();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05960.btn_Input_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        url += "?SCREN_ID=" + "ULDSTF05960.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listSectAhthQual&inputMessageId=SECT_AHTH_QUAL_INOUT";
        url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
        url += "&LIST_DD=" + edt_SDate.getValue();
        const sbmOptions = {
            id : "sbm_dts_List_1",
            action : "/SectionTypeChange.do",
            ref : "",
            target : "dts_List_1=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        url += "?SCREN_ID=" + "ULDSTF05960.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listNewGrwthCom&inputMessageId=SECT_AHTH_QUAL_INOUT";
        url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
        url += "&LIST_DD=" + edt_SDate.getValue();
        const sbmOptions = {
            id : "sbm_dts_List_2",
            action : "/SectionTypeChange.do",
            ref : "",
            target : "dts_List_2=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else if (MaxTab_01.getSelectedTabIndex() === 3) {
        url += "?SCREN_ID=" + "ULDSTF05960.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listHdnChamp&inputMessageId=SECT_AHTH_QUAL_INOUT";
        url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
        url += "&LIST_DD=" + edt_SDate.getValue();
        const sbmOptions = {
            id : "sbm_dts_List_3",
            action : "/SectionTypeChange.do",
            ref : "",
            target : "dts_List_3=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParIsur
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_ISUR_CD.getValue(); // 발행기관코드값
    arrPar[1] = txb_COM_NM.getValue(); // 발행기관명
    arrPar[2] = scwin.fr_SecuGrpId; // 명칭값을 포함할 컨트롤
    arrPar[3] = "9"; // 회사코드팝업 전체데이터
    return arrPar.length;
};

/**
 * @method
 * @name setParIsur
 * @description set Par Isur 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsur = function(arrPar) {
    const dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
        txb_COM_NM.setValue(arrPar[0].COM_NM);
    }
};

/**
 * @method
 * @name openDetail
 * @description open Detail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetail = async function() {
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        const options = {
            id: "ULDSTF05961",
            title: " 인증및자격 관리",
            type: "browserPopup",
            width: "820px",
            height: "860px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/lstproc/ULDSTF05961.gfm?nIndex=1", options);
    } else if (MaxTab_01.getSelectedTabIndex() === 3) {
        const options = {
            id: "ULDSTF05962",
            title: "라이징스타 관리",
            type: "browserPopup",
            width: "700px",
            height: "350px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/lstproc/ULDSTF05962.gfm?nIndex=2", options);
    }
};

/**
 * @method
 * @name setContnId
 * @description set Contn Id 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    if (Number(obj) > 0) {
        // 그리드에서 선택시
        scwin.gIsurCd = dts_List_1.getCellData(Number(obj), "ISUR_CD");
        scwin.gIsurNm = dts_List_1.getCellData(Number(obj), "ISUR_NM");
        scwin.gInputRnd = dts_List_1.getCellData(Number(obj), "INPUT_RND");
        scwin.gAcptNo = dts_List_1.getCellData(Number(obj), "ACPT_NO");
        scwin.gGubnStat = "U";
    }
};

/**
 * @method
 * @name filedown
 * @description filedown 처리
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.filedown = function(dtsObj) {
    const discls_doc_no = dtsObj.getCellData(dtsObj.getFocusedRowIndex(), "DISCLS_DOC_NO");
    const acpt_no = dtsObj.getCellData(dtsObj.getFocusedRowIndex(), "ACPT_NO");
    const attach_seq = dtsObj.getCellData(dtsObj.getFocusedRowIndex(), "ATTACH_SEQ");
    if (discls_doc_no !== "") {
        // 문서번호
        location.href = "/filedownload.do?file_id=" + discls_doc_no + "&attach_seq=" + attach_seq + "&gubun=12";
    }
};

/**
 * @method
 * @name input
 * @description 일괄등록
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.input = async function() {
    const options = {
        id: "ULDSTF05963",
        title: "라이징스타 등록",
        type: "browserPopup",
        width: "980px",
        height: "645px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/lstproc/ULDSTF05963.gfm", options);
};
